import java.util.*;

class Solution {
  public String findTheString(int[][] lcp) {
    int n = lcp.length;
    char[] a = new char[n];
    char c = 'a';
    for (int i = 0; i < n; i++)
      if (a[i] == 0) {
        if (c > 'z') return "";
        for (int j = 0; j < n; j++) if (lcp[i][j] > 0) a[j] = c;
        c++;
      }
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++) {
        int k = 0;
        while (i + k < n && j + k < n && a[i + k] == a[j + k]) k++;
        if (k != lcp[i][j]) return "";
      }
    return new String(a);
  }
}
